import {AdminReportOutletContext} from './bemusic-admin-report-page';
import {
  useRevenueReport,
  RevenueReportMetricType,
} from './use-revenue-report';
import {Trans} from '@ui/i18n/trans';
import {BarChart} from '@common/charts/bar-chart';
import {LineChart} from '@common/charts/line-chart';
import {useOutletContext} from 'react-router';
import {Fragment} from 'react';
import {FormattedCurrency} from '@ui/i18n/formatted-currency';

export function Component() {
  const {dateRange} = useOutletContext<AdminReportOutletContext>();

  const metrics: RevenueReportMetricType[] = [
    'revenue',
    'mrr',
    'products',
    'gateways',
    'subscriptions',
  ];

  const {data, isPending} = useRevenueReport({
    metrics,
    dateRange,
  });

  const revenue = data?.revenue;
  const mrr = data?.mrr;
  const products = data?.products;
  const gateways = data?.gateways;
  const subscriptions = data?.subscriptions;

  return (
    <Fragment>
      <div className="chart-grid">
        <LineChart
          isLoading={isPending}
          colSpan="col-span-8"
          title={<Trans message="Revenue over time" />}
          description={
            <Trans
              message=":count total revenue"
              values={{
                count: (
                  <FormattedCurrency
                    value={(revenue?.total ?? 0) / 100}
                    currency="EUR"
                  />
                ),
              }}
            />
          }
          data={revenue}
          hideLegend
        />
        <LineChart
          isLoading={isPending}
          colSpan="col-span-4"
          title={<Trans message="Monthly Recurring Revenue" />}
          description={
            <Trans
              message=":count average MRR"
              values={{
                count: (
                  <FormattedCurrency
                    value={(mrr?.total ?? 0) / 100}
                    currency="EUR"
                  />
                ),
              }}
            />
          }
          data={mrr}
          hideLegend
        />
        <BarChart
          isLoading={isPending}
          colSpan="col-span-6"
          title={<Trans message="Revenue by product" />}
          data={products}
          hideLegend
        />
        <BarChart
          isLoading={isPending}
          colSpan="col-span-6"
          title={<Trans message="Revenue by payment gateway" />}
          data={gateways}
          hideLegend
        />
        <LineChart
          isLoading={isPending}
          colSpan="col-span-8"
          title={<Trans message="Subscription payments" />}
          description={
            <Trans
              message=":count total payments"
              values={{count: subscriptions?.total ?? 0}}
            />
          }
          data={subscriptions}
          hideLegend
        />
      </div>
    </Fragment>
  );
}
