import {keepPreviousData, useQuery} from '@tanstack/react-query';
import {DateRangeValue} from '@ui/forms/input-field/date/date-range-picker/date-range-value';
import {apiClient} from '@common/http/query-client';
import {DatasetItem, ReportMetric} from '@common/admin/analytics/report-metric';

export interface RevenueReportMetric extends ReportMetric<DatasetItem> {}

export interface FetchRevenueReportResponse {
  revenue: RevenueReportMetric;
  mrr: RevenueReportMetric;
  products: RevenueReportMetric;
  gateways: RevenueReportMetric;
  subscriptions: RevenueReportMetric;
}

export type RevenueReportMetricType =
  | 'revenue'
  | 'mrr'
  | 'products'
  | 'gateways'
  | 'subscriptions';

interface Params {
  metrics: RevenueReportMetricType[];
  dateRange: DateRangeValue;
}

export function useRevenueReport(params: Params) {
  return useQuery({
    queryKey: ['revenue-report', params],
    queryFn: () => fetchRevenueReport(params),
    placeholderData: keepPreviousData,
  });
}

function fetchRevenueReport(params: Params) {
  return apiClient
    .get<FetchRevenueReportResponse>('reports/revenue', {
      params: {
        metrics: params.metrics.join(','),
        startDate: params.dateRange.start.toAbsoluteString(),
        endDate: params.dateRange.end.toAbsoluteString(),
        timezone: params.dateRange.start.timeZone || 'UTC',
      },
    })
    .then(response => response.data);
}
